import json,hashlib,re,tarfile
from pathlib import Path
b=Path(__file__).resolve().parent;repo=b.parents[1]
ids=['CVE-2010-4756','CVE-2018-20796','CVE-2019-9192','CVE-2026-100290','CVE-2026-115819','CVE-2026-126765','CVE-2013-4392','CVE-2019-1010022','CVE-2019-1010024','CVE-2019-1010025']
images={r:json.loads((b/f'phase2-{r}-probe.json').read_text())['image_id'] for r in ['api','web','tools']}
